const DEFAULT_ATTRIBUTE_GUESSES = [
  "children",
  "kids",
  "assets",
  "contents",
  "subassets",
  "items",
  "childAssets",
];

const KNOWN_FNS = ["resolveUri", "resolveMatrixAssetById", "resolveMatrixAssetByUrl"];

function parseAssetUriParts(uri) {
  const match = /^matrix-asset:\/\/([a-zA-Z0-9.-]+)\/(\d+)(?::.+)?$/.exec(
    String(uri ?? ""),
  );
  return match ? { domain: match[1], id: match[2] } : null;
}

function settleResult(settled) {
  if (settled.status === "fulfilled") {
    return { ok: true, data: settled.value };
  }
  const reason = settled.reason;
  return { ok: false, error: reason?.message ?? String(reason) };
}

/** Surfaces any array-valued key on a result -- the shape a "children" field would take if present. */
function findArrayLikeKeys(value) {
  if (!value || typeof value !== "object") return [];
  return Object.entries(value)
    .filter(([, v]) => Array.isArray(v))
    .map(([key, v]) => `${key} (length ${v.length})`);
}

/**
 * Tests Squiz Matrix's Content API children endpoint directly via fetch(),
 * bypassing info.fns entirely -- confirmed via docs.squiz.net that this is a
 * separate API surface (base URL {site}/__api/, Bearer token auth) from the
 * limited resolveUri/resolveMatrixAssetById/resolveMatrixAssetByUrl trio.
 */
async function probeContentApiChildren(token, baseUrl, assetId) {
  if (!token) {
    return { skipped: true, reason: "CONTENT_API_TOKEN environment variable is not set." };
  }
  if (!baseUrl) {
    return { skipped: true, reason: "No contentApiBaseUrl provided." };
  }
  if (!assetId) {
    return {
      skipped: true,
      reason: "No parentAsset selected, or its URI didn't parse into an asset ID.",
    };
  }

  const url = `${String(baseUrl).replace(/\/$/, "")}/__api/assets/${assetId}/children?limit=5000&data=metadata,attributes`;

  try {
    const res = await fetch(url, {
      headers: { Authorization: `Bearer ${token}` },
    });
    const text = await res.text();
    let body;
    try {
      body = JSON.parse(text);
    } catch {
      body = text.slice(0, 2000);
    }
    return { call: `GET ${url}`, status: res.status, ok: res.ok, body };
  } catch (err) {
    return { call: `GET ${url}`, ok: false, error: err?.message ?? String(err) };
  }
}

export default {
  async main(
    { parentAsset = "", urlOverride = "", extraAttributes = [], contentApiBaseUrl = "" } = {},
    info,
  ) {
    const { fns, env } = info;
    const parts = parentAsset ? parseAssetUriParts(parentAsset) : null;
    const filteredAttrs = Array.isArray(extraAttributes)
      ? extraAttributes.filter(Boolean)
      : [];
    const attrs = filteredAttrs.length ? filteredAttrs : DEFAULT_ATTRIBUTE_GUESSES;

    const resolveUriPromise = parentAsset
      ? fns.resolveUri(parentAsset)
      : Promise.resolve({ skipped: true, reason: "No parentAsset selected." });

    const byIdPromise = parts
      ? fns.resolveMatrixAssetById(parts.id, attrs)
      : Promise.resolve({
          skipped: true,
          reason: "No parentAsset selected, or its URI didn't parse into domain/id.",
        });

    const byUrlPromise = urlOverride
      ? fns.resolveMatrixAssetByUrl(urlOverride, attrs)
      : Promise.resolve({
          skipped: true,
          reason: "No urlOverride provided -- resolveMatrixAssetByUrl needs the asset's public URL, not its matrix-asset-uri.",
        });

    // Any other info.fns whose name suggests it might list/query children -- called defensively,
    // since this project doesn't have local docs access to confirm signatures ahead of time.
    const fnNames = Object.keys(fns || {});
    const candidateFnNames = fnNames.filter(
      (name) => /child|kids|list|query|search/i.test(name) && !KNOWN_FNS.includes(name),
    );
    const extraProbeArg = parts ? parts.id : parentAsset;
    const extraProbeSettled = await Promise.allSettled(
      candidateFnNames.map((name) => fns[name](extraProbeArg)),
    );

    const contentApiPromise = probeContentApiChildren(
      env?.CONTENT_API_TOKEN,
      contentApiBaseUrl,
      parts ? parts.id : null,
    );

    const [resolveUriResult, byIdResult, byUrlResult, contentApiResult] = await Promise.allSettled([
      resolveUriPromise,
      byIdPromise,
      byUrlPromise,
      contentApiPromise,
    ]);

    const resolveUriSettled = settleResult(resolveUriResult);
    const byIdSettled = settleResult(byIdResult);
    const byUrlSettled = settleResult(byUrlResult);
    const contentApiSettled = settleResult(contentApiResult);

    const display = {
      input: {
        parentAsset: parentAsset || "(none)",
        parsedDomainId: parts,
        attributesTried: attrs,
        urlOverride: urlOverride || "(none -- resolveMatrixAssetByUrl skipped)",
        contentApiBaseUrl: contentApiBaseUrl || "(none -- Content API children call skipped)",
        contentApiTokenSet: Boolean(env?.CONTENT_API_TOKEN),
      },
      availableFns: fnNames,
      resolveUri: {
        call: parentAsset ? `resolveUri(${JSON.stringify(parentAsset)})` : "(skipped)",
        result: resolveUriSettled,
        arrayLikeKeysFound: resolveUriSettled.ok
          ? findArrayLikeKeys(resolveUriSettled.data)
          : [],
      },
      resolveMatrixAssetById: {
        call: parts
          ? `resolveMatrixAssetById(${JSON.stringify(parts.id)}, ${JSON.stringify(attrs)})`
          : "(skipped)",
        result: byIdSettled,
        arrayLikeKeysFound: byIdSettled.ok ? findArrayLikeKeys(byIdSettled.data) : [],
      },
      resolveMatrixAssetByUrl: {
        call: urlOverride
          ? `resolveMatrixAssetByUrl(${JSON.stringify(urlOverride)}, ${JSON.stringify(attrs)})`
          : "(skipped)",
        result: byUrlSettled,
        arrayLikeKeysFound: byUrlSettled.ok ? findArrayLikeKeys(byUrlSettled.data) : [],
      },
      otherChildLikeFnsFound: candidateFnNames,
      otherFnProbeResults: candidateFnNames.map((name, i) => ({
        name,
        call: `${name}(${JSON.stringify(extraProbeArg)})`,
        ...settleResult(extraProbeSettled[i]),
      })),
      contentApiChildren: {
        note: "Direct fetch() against Squiz Matrix's Content API children endpoint, bypassing info.fns entirely. Requires CONTENT_API_TOKEN to be set and contentApiBaseUrl to be filled in.",
        result: contentApiSettled,
        arrayLikeKeysFound:
          contentApiSettled.ok && contentApiSettled.data?.body
            ? findArrayLikeKeys(contentApiSettled.data.body)
            : [],
      },
    };

    return /*html*/ `<div class="asset-children-picker">
      <details open>
        <summary>Asset Children Picker</summary>
        <p>Pick a folder or parent asset above, then check below for any array-valued field (see "arrayLikeKeysFound") across every resolution method -- that's what a real children list would look like.</p>
        <pre><code>${JSON.stringify(display, null, 2)}</code></pre>
      </details>
    </div>`;
  },
};
